import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Role = 'Student' | 'Teacher' | 'Parent';
export type Language = 'English' | 'Telugu';
export type ClassLevel = 'Preschool' | 'Class 1' | 'Class 2' | 'Class 3' | 'Class 4' | 'Class 5';
export type Board = 'CBSE' | 'Telangana State Board' | null;
export type HouseName = 'Aetherion' | 'Ignivar' | 'Verdantis' | 'Lunaris' | null;

export interface UserProgress {
  lessonsCompleted: string[];
  quizzesCompleted: string[];
  gamesPlayed: string[];
  starsEarned: number;
  xp: number;
  housePoints: number;
  unlockedAvatars: string[];
  currentAvatar: string;
}

export interface UserProfile {
  schoolName: string;
  classLevel: ClassLevel;
  section: string;
  rollNumber: string;
  studentName: string;
  role: Role;
  language: Language;
  board: Board;
  house: HouseName;
  progress: UserProgress;
}

export interface Lesson {
  id: string;
  title: string;
  subject: string;
  description: string;
  videoUrl?: string;
  imageUrl?: string;
  ruralExample: string;
  voiceOverEn: string;
  voiceOverTe: string;
}

export interface QuizQuestion {
  id: string;
  question: string;
  options: { text: string; imageUrl?: string; isCorrect: boolean }[];
  explanation: string;
}

export interface Quiz {
  lessonId: string;
  questions: QuizQuestion[];
}

export interface Game {
  lessonId: string;
  type: 'Math' | 'English' | 'EVS';
  title: string;
}

