            setProfile(p => ({ ...p, role: 'Teacher' } as UserProfile));
            navigateTo('login');
          }} />
          <RoleCard role="Parent" icon="👨‍👩‍👧" color="bg-purple-400" onClick={() => {
            setProfile(p => ({ ...p, role: 'Parent' } as UserProfile));
            navigateTo('login');
          }} />
        </div>
      </div>
    );
  }

  if (screen === 'login') {
    return <LoginScreen profile={profile} setProfile={setProfile} onComplete={() => navigateTo('language_selection')} />;
  }

  if (screen === 'language_selection') {
    return (
