import React, { useState, useEffect, useCallback, useRef } from 'react';
// Removed non-existent 'Quiz' import to fix module resolution error
import { UserProfile, UserProgress, Role, Language, ClassLevel, Board, HouseName, Lesson, Avatar } from './types';
import { SYLLABUS, HOUSES, PRESCHOOL_AVATARS, CLASS_1_5_AVATARS } from './constants';
import { Button, Card, Header, AudioPlayer } from './components/UI';
import { askMentor } from './services/geminiService';

// --- MAIN APP COMPONENT ---
const App: React.FC = () => {
  // Navigation State
  const [screen, setScreen] = useState<string>('splash');
  const [history, setHistory] = useState<string[]>(['splash']);

  // User State
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [currentLesson, setCurrentLesson] = useState<Lesson | null>(null);
  const [chatHistory, setChatHistory] = useState<{ role: string, text: string }[]>([]);
  const [justUnlocked, setJustUnlocked] = useState<Avatar | null>(null);

  // Persistent Storage logic
  useEffect(() => {
    const saved = localStorage.getItem('rural_learn_user');
    if (saved) {
      const data = JSON.parse(saved);
      setProfile(data);
    }
  }, []);

  useEffect(() => {
    if (profile) {
      localStorage.setItem('rural_learn_user', JSON.stringify(profile));
      checkAvatarUnlocks();
    }
  }, [profile?.progress.lessonsCompleted.length, profile?.progress.quizzesCompleted.length, profile?.progress.housePoints]);

  const checkAvatarUnlocks = () => {
    if (!profile) return;
    const pool = profile.classLevel === 'Preschool' ? PRESCHOOL_AVATARS : CLASS_1_5_AVATARS;
    const { progress } = profile;

    pool.forEach(avatar => {
      if (avatar.isStarter) return;
      if (progress.unlockedAvatars.includes(avatar.id)) return;

      let unlocked = false;
      const req = avatar.unlockRequirement;
      if (!req) return;

      switch (req.type) {
        case 'lessons': if (progress.lessonsCompleted.length >= req.value) unlocked = true; break;
        case 'quizzes': if (progress.quizzesCompleted.length >= req.value) unlocked = true; break;
        case 'points': if (progress.housePoints >= req.value) unlocked = true; break;
      }

      if (unlocked) {
        setProfile(p => {
          if (!p) return null;
          return {
            ...p,
            progress: {
              ...p.progress,
              unlockedAvatars: [...p.progress.unlockedAvatars, avatar.id]
            }
          };
        });
        setJustUnlocked(avatar);
      }
    });
  };

  // Navigation Logic
  const navigateTo = (newScreen: string) => {
    setHistory(prev => [...prev, screen]);
    setScreen(newScreen);
  };

  const goBack = () => {
    if (history.length > 1) {
      const last = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setScreen(last);
    }
  };

  const goHome = () => {
    if (profile?.classLevel === 'Preschool') setScreen('preschool_map');
    else setScreen('hogwarts_map');
    setHistory(['splash']);
  };

  // --- SCREEN RENDERING ---

  if (justUnlocked) {
    return (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
        <div className="bg-white rounded-3xl p-10 flex flex-col items-center text-center max-w-sm border-8 border-yellow-400 animate-in fade-in zoom-in duration-300">
          <div className="text-6xl mb-4">✨✨✨</div>
          <h2 className="bangers text-4xl text-blue-800 mb-6 uppercase">New Avatar Unlocked!</h2>
          <div className="w-48 h-48 rounded-2xl overflow-hidden mb-6 shadow-2xl shadow-yellow-500/50">
            <img src={justUnlocked.image} className="w-full h-full object-cover" />
          </div>
          <p className="text-2xl font-bold mb-8">{justUnlocked.name}</p>
          <Button variant="magical" onClick={() => setJustUnlocked(null)}>Amazing! 🪄</Button>
        </div>
      </div>
    );
  }

  if (screen === 'splash') {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-gradient-to-b from-blue-400 to-indigo-600 text-white p-10 text-center" onClick={() => navigateTo('role_selection')}>
        <div className="animate-bounce text-8xl mb-8">🎒</div>
        <h1 className="bangers text-7xl mb-4 tracking-widest drop-shadow-lg">RURAL LEARN</h1>
        <p className="text-2xl font-medium animate-pulse">Touch to Start Magic! ✨</p>
      </div>
    );
  }

  if (screen === 'role_selection') {
    return (
      <div className="min-h-screen bg-sky-50 flex flex-col items-center justify-center p-6">
        <h2 className="text-4xl font-bold text-blue-900 mb-12 text-center">Who are you?</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 w-full max-w-4xl">
          <RoleCard role="Student" icon="🧒" color="bg-yellow-400" onClick={() => { setProfile(p => ({ ...p, role: 'Student' } as UserProfile)); navigateTo('login'); }} />
          <RoleCard role="Teacher" icon="👩‍🏫" color="bg-green-400" onClick={() => { setProfile(p => ({ ...p, role: 'Teacher' } as UserProfile)); navigateTo('login'); }} />
          <RoleCard role="Parent" icon="👨‍👩‍👧" color="bg-purple-400" onClick={() => { setProfile(p => ({ ...p, role: 'Parent' } as UserProfile)); navigateTo('login'); }} />
        </div>
      </div>
    );
  }

  if (screen === 'login') {
    return <LoginScreen profile={profile} setProfile={setProfile} onComplete={() => navigateTo('language_selection')} />;
  }

  if (screen === 'language_selection') {
    return (
      <div className="min-h-screen bg-sky-50 flex flex-col items-center justify-center p-6">
        <h2 className="text-4xl font-bold text-blue-900 mb-12">Choose Language</h2>
        <div className="flex gap-8">
          <Button onClick={() => { setProfile(p => ({ ...p, language: 'English' } as UserProfile)); navigateTo('class_selection'); }}>English 🇬🇧</Button>
          <Button onClick={() => { setProfile(p => ({ ...p, language: 'Telugu' } as UserProfile)); navigateTo('class_selection'); }}>తెలుగు 🇮🇳</Button>
        </div>
      </div>
    );
  }

  if (screen === 'class_selection') {
    return <ClassSelectionScreen onSelect={(lvl) => {
      setProfile(p => ({ ...p, classLevel: lvl } as UserProfile));
      if (lvl === 'Preschool') navigateTo('preschool_map');
      else navigateTo('board_selection');
    }} />;
  }

  if (screen === 'board_selection') {
    return (
      <div className="min-h-screen bg-sky-50 flex flex-col items-center justify-center p-6">
        <h2 className="text-4xl font-bold text-blue-900 mb-12">Select Board</h2>
        <div className="flex flex-col gap-6">
          <Button onClick={() => { setProfile(p => ({ ...p, board: 'CBSE' } as UserProfile)); navigateTo('sorting_ceremony'); }}>CBSE</Button>
          <Button onClick={() => { setProfile(p => ({ ...p, board: 'Telangana State Board' } as UserProfile)); navigateTo('sorting_ceremony'); }}>Telangana Board</Button>
        </div>
      </div>
    );
  }

  if (screen === 'sorting_ceremony') {
    return <SortingCeremony onComplete={(house) => {
      setProfile(p => ({ ...p, house } as UserProfile));
      navigateTo('avatar_selection');
    }} />;
  }

  if (screen === 'avatar_selection') {
    return <AvatarSelectionScreen 
      profile={profile!} 
      onSelect={(avatarId) => {
        setProfile(p => ({ ...p, progress: { ...p?.progress, currentAvatar: avatarId } } as UserProfile));
        goHome();
      }} 
    />;
  }

  if (screen === 'preschool_map') {
    return <PreschoolMap onNodeClick={(lesson) => { setCurrentLesson(lesson); navigateTo('lesson_player'); }} progress={profile?.progress} onAvatarClick={() => navigateTo('avatar_selection')} />;
  }

  if (screen === 'hogwarts_map') return <HogwartsMap onLocationClick={(loc) => navigateTo(loc)} profile={profile} />;

  if (screen === 'library') {
    return (
      <div className="min-h-screen bg-sky-50 p-6">
        <Header title="Library Tower" onBack={goBack} onHome={goHome} />
        <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
          {Object.entries(SYLLABUS[profile?.classLevel || 'Class 1']).map(([subject, lessons]) => (
            <div key={subject} className="mb-6">
              <h3 className="text-2xl font-bold text-blue-800 mb-4">{subject}</h3>
              <div className="space-y-3">
                {(lessons as Lesson[]).map(l => (
                  <Card key={l.id} className="cursor-pointer hover:border-blue-400" onClick={() => { setCurrentLesson(l); navigateTo('lesson_player'); }}>
                    <div className="flex justify-between items-center">
                      <span className="text-lg font-medium">{l.title}</span>
                      {profile?.progress?.lessonsCompleted?.includes(l.id) && <span>✅</span>}
                    </div>
                  </Card>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (screen === 'lesson_player') {
    return <LessonPlayer lesson={currentLesson} onComplete={() => {
      setProfile(p => {
        if (!p) return null;
        if (p.progress.lessonsCompleted.includes(currentLesson!.id)) return p;
        return {
          ...p,
          progress: {
            ...p.progress,
            lessonsCompleted: [...p.progress.lessonsCompleted, currentLesson!.id],
            xp: p.progress.xp + 50
          }
        };
      });
      navigateTo('quiz');
    }} onBack={goBack} profile={profile} />;
  }

  if (screen === 'quiz') {
    return (
      <QuizScreen 
        lessonId={currentLesson?.id || ''} 
        onComplete={(score) => {
          setProfile(p => {
            if (!p) return null;
            return {
              ...p,
              progress: {
                ...p.progress,
                quizzesCompleted: [...p.progress.quizzesCompleted, currentLesson!.id],
                starsEarned: p.progress.starsEarned + score,
                housePoints: p.progress.housePoints + (score * 10)
              }
            };
          });
          navigateTo('game');
        }}
        onBack={goBack}
        language={profile?.language || 'English'}
      />
    );
  }

  if (screen === 'game') {
    return (
      <div className="min-h-screen bg-orange-50 flex flex-col items-center justify-center p-6 text-center">
        <h2 className="text-5xl font-bold text-orange-600 mb-8 bangers">GAME TIME!</h2>
        <Card className="max-w-md w-full p-10">
          <div className="text-6xl mb-6">🧪</div>
          <p className="text-2xl mb-8">Mix the magical potion for {currentLesson?.title}!</p>
          <Button variant="magical" onClick={() => {
            setProfile(p => {
              if (!p) return null;
              return {
                ...p,
                progress: {
                  ...p.progress,
                  gamesPlayed: [...p.progress.gamesPlayed, currentLesson!.id],
                  xp: p.progress.xp + 100
                }
              };
            });
            goHome();
          }}>Play & Win 100 XP!</Button>
        </Card>
      </div>
    );
  }

  if (screen === 'chatbot_tower') return <ChatbotScreen chatHistory={chatHistory} setChatHistory={setChatHistory} language={profile?.language || 'English'} onBack={goBack} />;

  if (screen === 'friends') {
    return (
      <div className="min-h-screen bg-green-50 p-6">
        <Header title="Friends Forest" onBack={goBack} onHome={goHome} />
        <div className="grid grid-cols-2 md:grid-cols-3 gap-6 mt-10">
          {[1,2,3,4,5].map(f => (
            <Card key={f} className="flex flex-col items-center p-4">
              <div className="w-20 h-20 rounded-full bg-yellow-200 mb-2 flex items-center justify-center text-4xl overflow-hidden">
                <img src={`https://picsum.photos/seed/friend${f}/100`} className="w-full h-full object-cover" />
              </div>
              <span className="font-bold">Friend {f}</span>
              <span className="text-sm text-green-600">Online 🟢</span>
              <div className="flex gap-2 mt-2">
                <button className="text-2xl">👋</button>
                <button className="text-2xl">🪄</button>
                <button className="text-2xl">✨</button>
              </div>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  if (screen === 'leaderboard') {
    return (
      <div className="min-h-screen bg-indigo-50 p-6">
        <Header title="Hall of Fame" onBack={goBack} onHome={goHome} />
        <div className="mt-10 max-w-lg mx-auto space-y-4">
          {HOUSES.sort((a,b) => b.name.length - a.name.length).map((h, i) => (
            <div key={h.name} className={`flex items-center justify-between p-6 rounded-2xl ${h.color} text-white shadow-lg`}>
              <div className="flex items-center gap-4">
                <span className="text-3xl font-bold">{i+1}</span>
                <span className="text-4xl">{h.icon}</span>
                <div>
                  <div className="text-2xl font-bold">{h.name}</div>
                  <div className="text-sm opacity-80">{h.trait}</div>
                </div>
              </div>
              <div className="text-3xl font-bold">{(500 - i * 50) + (profile?.house === h.name ? profile.progress.housePoints : 0)} pts</div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (screen === 'student_dashboard') return <StudentDashboard profile={profile} onBack={goBack} onLogout={() => { localStorage.removeItem('rural_learn_user'); setProfile(null); setScreen('splash'); }} />;

  return <div>Screen not found</div>;
};

