const QuizScreen: React.FC<{ lessonId: string, onComplete: (score: number) => void, onBack: () => void, language: string }> = ({ lessonId, onComplete, onBack, language }) => {
  const [currentQ, setCurrentQ] = useState(0);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);
  const questions = [
    { text: "What color is the sky?", options: ["Blue", "Red", "Green"], correct: 0 },
    { text: "How many legs does a cow have?", options: ["2", "4", "6"], correct: 1 }
  ];
  const handleAnswer = (idx: number) => {
    if (idx === questions[currentQ].correct) setScore(s => s + 1);
    if (currentQ < questions.length - 1) setCurrentQ(currentQ + 1);
    else setFinished(true);
  };
  if (finished) {
    return (
      <div className="min-h-screen bg-sky-50 flex flex-col items-center justify-center p-6 text-center">
        <div className="text-9xl mb-8 animate-bounce">🎊</div>
        <h2 className="text-5xl font-bold text-blue-800 mb-4 uppercase">Well Done!</h2>
        <p className="text-2xl mb-8">You earned {score} magical stars!</p>
        <Button onClick={() => onComplete(score)}>Collect Rewards 🎁</Button>
      </div>
    );
  }
  return (
    <div className="min-h-screen bg-sky-50">
      <Header title="Knowledge Quest" onBack={onBack} onHome={() => {}} />
      <div className="p-6 max-w-xl mx-auto mt-10">
        <div className="text-center mb-10">
          <span className="text-xl font-bold text-blue-600 uppercase">Question {currentQ + 1} of {questions.length}</span>
          <div className="w-full bg-gray-200 h-4 rounded-full mt-4">
            <div className="bg-blue-600 h-full rounded-full transition-all" style={{ width: `${((currentQ + 1) / questions.length) * 100}%` }}></div>
          </div>
        </div>
        <Card className="p-10 text-center">
          <h3 className="text-3xl font-bold mb-10">{questions[currentQ].text}</h3>
          <div className="space-y-4">
            {questions[currentQ].options.map((opt, i) => (
              <button key={i} onClick={() => handleAnswer(i)} className="w-full p-6 text-2xl border-4 border-blue-100 rounded-2xl hover:bg-blue-50 transition-colors font-medium active:bg-blue-100">{opt}</button>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
};

const ChatbotScreen: React.FC<{ chatHistory: any, setChatHistory: any, language: string, onBack: () => void }> = ({ chatHistory, setChatHistory, language, onBack }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  useEffect(() => { scrollRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory]);
  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg = { role: 'user', text: input };
    setChatHistory([...chatHistory, userMsg]);
    const currentInput = input;
    setInput('');
    setLoading(true);
    const reply = await askMentor(currentInput, language as any);
    setChatHistory((prev: any) => [...prev, { role: 'mentor', text: reply }]);
    setLoading(false);
  };
  return (
    <div className="min-h-screen bg-purple-50 flex flex-col">
      <Header title="Magical Mentor" onBack={onBack} onHome={() => {}} />
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {chatHistory.length === 0 && (
          <div className="text-center p-10">
            <div className="text-6xl mb-4 animate-pulse">✨</div>
            <p className="text-xl text-purple-800">Hi! I'm Sparky. Ask me anything about your lessons!</p>
          </div>
        )}
        {chatHistory.map((msg: any, i: number) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 rounded-2xl text-lg ${msg.role === 'user' ? 'bg-purple-600 text-white rounded-br-none shadow-purple-200 shadow-lg' : 'bg-white shadow-md rounded-bl-none'}`}>{msg.text}</div>
          </div>
        ))}
        {loading && <div className="text-purple-400 italic p-2 animate-pulse">Thinking of a magical answer...</div>}
        <div ref={scrollRef} />
      </div>
      <div className="p-4 bg-white border-t flex gap-2">
        <input value={input} onChange={e => setInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && handleSend()} placeholder="Ask Sparky..." className="flex-1 p-4 border-2 rounded-xl text-lg outline-none focus:border-purple-400 shadow-inner" />
        <Button onClick={handleSend} className="px-6 py-2">✨</Button>
      </div>
    </div>
  );
};

const StudentDashboard: React.FC<{ profile: UserProfile | null, onBack: () => void, onLogout: () => void }> = ({ profile, onBack, onLogout }) => {
  if (!profile) return null;
  const avatarId = profile.progress?.currentAvatar || '';
  const pool = profile.classLevel === 'Preschool' ? PRESCHOOL_AVATARS : CLASS_1_5_AVATARS;
  const avatarImg = pool.find(a => a.id === avatarId)?.image || pool[0].image;
  const house = HOUSES.find(h => h.name === profile.house);

  return (
    <div className="min-h-screen bg-sky-50">
      <Header title="My Magical Scroll" onBack={onBack} onHome={() => {}} />
      <div className="p-6 max-w-xl mx-auto space-y-6">
        <Card className="flex flex-col items-center text-center p-10 bg-gradient-to-br from-white to-blue-50">
          <div className={`w-32 h-32 rounded-full border-8 mb-4 overflow-hidden shadow-xl ${house?.color.replace('bg-', 'border-') || 'border-yellow-400'}`}>
             <img src={avatarImg} alt="Avatar" className="w-full h-full object-cover" />
          </div>
          <h2 className="text-3xl font-bold text-blue-900 uppercase">{profile.studentName}</h2>
          <p className="text-lg opacity-70 mb-4">Roll: {profile.rollNumber} | {profile.classLevel}</p>
          {profile.classLevel !== 'Preschool' && profile.house && (
            <div className={`px-4 py-1 rounded-full text-white font-bold ${house?.color || 'bg-gray-400'}`}>House {profile.house}</div>
          )}
        </Card>
        <div className="grid grid-cols-2 gap-4">
          <StatCard icon="✨" label="XP" value={(profile.progress?.xp || 0).toString()} />
          <StatCard icon="⭐" label="Stars" value={(profile.progress?.starsEarned || 0).toString()} />
          <StatCard icon="📚" label="Lessons" value={(profile.progress?.lessonsCompleted?.length || 0).toString()} />
          <StatCard icon="🏰" label="House Points" value={(profile.progress?.housePoints || 0).toString()} />
        </div>
        <Card>
          <h3 className="text-xl font-bold mb-4 uppercase text-center">Avatars Unlocked</h3>
          <div className="flex flex-wrap gap-4 justify-center">
            {pool.map(a => {
              const unlocked = (profile.progress?.unlockedAvatars?.includes(a.id)) || a.isStarter;
              return (
                <div key={a.id} className={`w-12 h-12 rounded-full border-2 overflow-hidden transition-all ${unlocked ? 'border-yellow-400 grayscale-0 scale-100' : 'bg-gray-200 border-gray-300 grayscale opacity-40 scale-90'}`}>
                  {unlocked ? <img src={a.image} className="w-full h-full object-cover" alt="Unlocked" /> : <div className="w-full h-full flex items-center justify-center text-xs">🔒</div>}
                </div>
              );
            })}
          </div>
        </Card>
        <Button variant="danger" className="w-full" onClick={onLogout}>Logout</Button>
      </div>
    </div>
  );
};

