import { askMentor } from './services/geminiService';

const App: React.FC = () => {
  const [screen, setScreen] = useState<string>('splash');
  const [history, setHistory] = useState<string[]>(['splash']);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [currentLesson, setCurrentLesson] = useState<Lesson | null>(null);
  const [chatHistory, setChatHistory] = useState<{ role: string, text: string }[]>([]);
  const [justUnlocked, setJustUnlocked] = useState<Avatar | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('rural_learn_v2');
    if (saved) {
      try {
        setProfile(JSON.parse(saved));
      } catch (e) {
        console.error("Storage corrupt", e);
      }
    }
  }, []);

  useEffect(() => {
    if (profile) localStorage.setItem('rural_learn_v2', JSON.stringify(profile));
  }, [profile]);

  const navigateTo = (newScreen: string) => {
    setHistory(prev => [...prev, screen]);
    setScreen(newScreen);
  };

  const goBack = () => {
    if (history.length > 1) {
      const last = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setScreen(last);
    }
  };

  const goHome = () => {
    if (profile?.classLevel === 'Preschool') setScreen('preschool_map');
    else setScreen('hogwarts_map');
    setHistory(['splash']);
  };

  // --- Screens ---

  if (screen === 'splash') {
    return (
      <div className="h-screen flex flex-col items-center justify-center magic-bg text-white p-10 text-center overflow-hidden" onClick={() => navigateTo('role_selection')}>
        <div className="float text-9xl mb-8 drop-shadow-[0_0_20px_rgba(255,255,255,0.5)]">🎒</div>
        <h1 className="bangers text-8xl mb-4 tracking-widest text-yellow-400 drop-shadow-lg uppercase">Rural Learn</h1>
        <p className="text-3xl font-medium animate-pulse opacity-80">Tap to Enter the Magic...</p>
        <div className="absolute inset-0 pointer-events-none opacity-20">
          {[...Array(20)].map((_, i) => <div key={i} className="sparkle-particle" style={{top: `${Math.random()*100}%`, left: `${Math.random()*100}%`, animationDelay: `${Math.random()*5}s`}} />)}
        </div>
      </div>
    );
  }

  if (screen === 'role_selection') {
    return (
      <div className="min-h-screen magic-bg flex flex-col items-center justify-center p-6 text-white">
        <h2 className="text-5xl font-bold mb-12 bangers tracking-widest text-yellow-400">Who are you?</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-10 w-full max-w-5xl">
          <RoleCard role="Student" icon="🧒" color="bg-blue-500" onClick={() => { setProfile(p => ({ ...p, role: 'Student' } as UserProfile)); navigateTo('login'); }} />
          <RoleCard role="Teacher" icon="👩‍🏫" color="bg-emerald-500" onClick={() => { setProfile(p => ({ ...p, role: 'Teacher' } as UserProfile)); navigateTo('login'); }} />
          <RoleCard role="Parent" icon="👨‍👩‍👧" color="bg-purple-500" onClick={() => { setProfile(p => ({ ...p, role: 'Parent' } as UserProfile)); navigateTo('login'); }} />
        </div>
      </div>
    );
  }

  if (screen === 'login') {
    return <LoginScreen profile={profile} setProfile={setProfile} onComplete={() => navigateTo('language_selection')} />;
  }

  if (screen === 'language_selection') {
    return (
      <div className="min-h-screen magic-bg flex flex-col items-center justify-center p-6 text-white">
        <h2 className="text-5xl font-bold mb-12 bangers text-yellow-400">Choose Language</h2>
        <div className="flex gap-10">
          <Button variant="magical" onClick={() => { setProfile(p => ({ ...p, language: 'English' } as UserProfile)); navigateTo('class_selection'); }}>English 🇬🇧</Button>
          <Button variant="magical" onClick={() => { setProfile(p => ({ ...p, language: 'Telugu' } as UserProfile)); navigateTo('class_selection'); }}>తెలుగు 🇮🇳</Button>
        </div>
      </div>
    );
  }

  if (screen === 'class_selection') {
    return <ClassSelectionScreen onSelect={(lvl) => {
      setProfile(p => ({ ...p, classLevel: lvl } as UserProfile));
      if (lvl === 'Preschool') navigateTo('preschool_avatar_selection');
      else navigateTo('board_selection');
    }} />;
  }

  if (screen === 'preschool_avatar_selection') {
    return <AvatarSelectionScreen pool={PRESCHOOL_AVATARS} onSelect={(id) => {
      setProfile(p => ({ ...p, progress: { ...p?.progress, currentAvatar: id, unlockedAvatars: [id] } } as UserProfile));
      navigateTo('preschool_map');
    }} profile={profile!} isPreschool={true} />;
  }

  if (screen === 'board_selection') {
    return (
      <div className="min-h-screen magic-bg flex flex-col items-center justify-center p-6 text-white">
        <h2 className="text-5xl font-bold mb-12 bangers text-yellow-400 uppercase">Select Board</h2>
        <div className="flex flex-col gap-8 w-full max-w-sm">
          <Button variant="magical" onClick={() => { setProfile(p => ({ ...p, board: 'CBSE' } as UserProfile)); navigateTo('sorting_ceremony'); }}>CBSE</Button>
          <Button variant="magical" onClick={() => { setProfile(p => ({ ...p, board: 'Telangana State Board' } as UserProfile)); navigateTo('sorting_ceremony'); }}>Telangana Board</Button>
        </div>
      </div>
    );
  }

  if (screen === 'sorting_ceremony') {
    return <SortingCeremony language={profile?.language || 'English'} onComplete={(house) => {
      setProfile(p => ({ ...p, house } as UserProfile));
      navigateTo('class_avatar_selection');
    }} />;
  }

  if (screen === 'class_avatar_selection') {
    return <AvatarSelectionScreen pool={CLASS_1_5_AVATARS} onSelect={(id) => {
      setProfile(p => ({ ...p, progress: { ...p?.progress, currentAvatar: id, unlockedAvatars: [id] } } as UserProfile));
      navigateTo('hogwarts_map');
    }} profile={profile!} isPreschool={false} />;
  }

  if (screen === 'preschool_map') {
    return <PreschoolMap onNodeClick={(lesson) => { setCurrentLesson(lesson); navigateTo('lesson_player'); }} profile={profile} onAvatarClick={() => navigateTo('student_dashboard')} />;
  }

  if (screen === 'hogwarts_map') return <HogwartsMap onLocationClick={(loc) => navigateTo(loc)} profile={profile} />;

  if (screen === 'library') {
    const subjects = SYLLABUS[profile?.classLevel || 'Class 1'] || {};
    return (
      <div className="min-h-screen magic-bg p-6 text-white">
        <Header title="Library Tower" onBack={goBack} onHome={goHome} />
        <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-6 max-w-5xl mx-auto">
          {Object.entries(subjects).map(([subject, lessons]) => (
            <div key={subject} className="bg-white/5 p-6 rounded-3xl border border-white/10">
              <h3 className="text-3xl font-bold text-yellow-400 mb-6 bangers tracking-widest uppercase">{subject}</h3>
              <div className="space-y-4">
                {(lessons as Lesson[]).map(l => (
                  <div key={l.id} className="p-4 bg-white/10 rounded-2xl cursor-pointer hover:bg-white/20 transition-colors flex justify-between items-center" onClick={() => { setCurrentLesson(l); navigateTo('lesson_player'); }}>
                    <span className="text-xl font-medium">{l.title}</span>
                    {profile?.progress?.lessonsCompleted?.includes(l.id) && <span className="text-2xl">✅</span>}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (screen === 'lesson_player') {
    return <LessonPlayer lesson={currentLesson} onComplete={() => navigateTo('quiz')} onBack={goBack} profile={profile} />;
  }

  if (screen === 'quiz') {
    return <QuizScreen lessonId={currentLesson?.id || ''} onComplete={(score) => {
      setProfile(p => {
        if (!p || !currentLesson) return null;
        return { ...p, progress: { ...p.progress, quizzesCompleted: [...p.progress.quizzesCompleted, currentLesson.id], starsEarned: p.progress.starsEarned + score, housePoints: p.progress.housePoints + (score * 10) } };
      });
      navigateTo('game');
    }} onBack={goBack} language={profile?.language || 'English'} />;
  }

  if (screen === 'game') {
    return (
      <div className="min-h-screen bg-indigo-900 flex flex-col items-center justify-center p-6 text-center text-white">
        <h2 className="text-6xl font-bold text-yellow-400 mb-10 bangers tracking-widest">GAME TIME!</h2>
        <Card className="max-w-md w-full p-10 bg-indigo-800 border-yellow-400">
          <div className="text-8xl mb-8 float">🎮</div>
          <p className="text-2xl mb-10">Win the magic challenge for {currentLesson?.title}!</p>
          <Button variant="magical" onClick={() => {
            setProfile(p => {
              if (!p || !currentLesson) return null;
              return { ...p, progress: { ...p.progress, gamesPlayed: [...p.progress.gamesPlayed, currentLesson.id], xp: p.progress.xp + 100 } };
            });
            goHome();
          }}>Play & Win!</Button>
        </Card>
      </div>
    );
  }

  if (screen === 'student_dashboard') {
    return <StudentDashboard profile={profile} onBack={goBack} onLogout={() => { localStorage.removeItem('rural_learn_v2'); setProfile(null); setScreen('splash'); }} />;
  }

  if (screen === 'chatbot_tower') return <ChatbotScreen chatHistory={chatHistory} setChatHistory={setChatHistory} language={profile?.language || 'English'} onBack={goBack} />;

  return <div className="p-10 text-white text-center">Loading the Magic...</div>;
};

