const SortingCeremony: React.FC<{ onComplete: (h: HouseName) => void, language: string, onBack: () => void }> = ({ onComplete, language, onBack }) => {
  const [phase, setPhase] = useState<'attraction' | 'path' | 'confirmation' | 'reveal'>('attraction');
  const [selectedHouse, setSelectedHouse] = useState<typeof HOUSES[0] | null>(null);

  const handleSelectObject = (house: typeof HOUSES[0]) => {
    setSelectedHouse(house);
    setPhase('path');
    setTimeout(() => setPhase('confirmation'), 3000);
  };

  const handleConfirm = () => {
    setPhase('reveal');
    const msg = new SpeechSynthesisUtterance();
    msg.text = language === 'Telugu' ? selectedHouse!.audioTe : selectedHouse!.audioEn;
    msg.lang = language === 'Telugu' ? 'te-IN' : 'en-US';
    window.speechSynthesis.speak(msg);
  };

  if (phase === 'reveal') {
    return (
      <div className={`min-h-screen ${selectedHouse?.color} flex flex-col items-center justify-center text-white overflow-hidden p-10`}>
        <div className="animate-flag w-64 h-[28rem] bg-white/20 backdrop-blur-md rounded-b-[2rem] border-x-8 border-b-8 border-yellow-400/50 flex flex-col items-center p-10 shadow-2xl">
          <div className="text-[10rem] mb-12 drop-shadow-2xl">{selectedHouse?.icon}</div>
          <h1 className="bangers text-6xl tracking-[0.3em] uppercase">{selectedHouse?.name}</h1>
        </div>
        <div className="mt-16 text-center space-y-6">
          <p className="text-4xl font-bold animate-pulse">{language === 'Telugu' ? selectedHouse?.audioTe : `Welcome to ${selectedHouse?.name}!`}</p>
          <div className="flex flex-col gap-4">
             <Button variant="primary" className="py-4 text-2xl uppercase bangers" onClick={() => onComplete(selectedHouse!.name as HouseName)}>Enter School 🏰</Button>
             <Button variant="secondary" className="py-2 text-xl" onClick={onBack}>Change Class / Board 🪄</Button>
          </div>
        </div>
      </div>
    );
  }

  if (phase === 'confirmation') {
    return (
      <div className="min-h-screen bg-indigo-950 flex flex-col items-center justify-center text-white p-10">
        <div className={`w-72 h-72 rounded-full ${selectedHouse?.color} flex items-center justify-center text-9xl shadow-[0_0_100px_rgba(255,255,255,0.4)] animate-pulse cursor-pointer hover:scale-110 transition-transform`} onClick={handleConfirm}>
          {selectedHouse?.icon}
        </div>
        <p className="mt-16 text-4xl font-bold bangers tracking-widest animate-bounce uppercase">CAST YOUR SPELL! 🪄</p>
      </div>
    );
  }

  if (phase === 'path') {
    return (
      <div className="min-h-screen bg-indigo-950 flex flex-col items-center justify-center text-white p-10 overflow-hidden">
        <div className={`w-4 h-screen bg-gradient-to-b ${selectedHouse?.pathColor} absolute top-0 shadow-[0_0_50px_rgba(255,255,255,0.2)]`}></div>
        <div className="text-[12rem] z-10 animate-bounce">{selectedHouse?.object}</div>
        <p className="mt-12 text-3xl font-medium tracking-widest opacity-80 uppercase">The magic path forms...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-indigo-950 flex flex-col items-center justify-center p-6 text-center text-white overflow-hidden">
      <h2 className="text-5xl font-bold mb-6 bangers tracking-widest text-yellow-400 uppercase">Sorting Ceremony</h2>
      <p className="text-2xl mb-16 opacity-70 max-w-xl italic">
        {language === 'Telugu' ? 'మాయ మీ మనసును చూపిస్తుంది. మీకు నచ్చినదాన్ని అనుసరించండి.' : 'Magic reveals who you are. Follow what feels right.'}
      </p>
      <div className="grid grid-cols-2 gap-16 md:gap-32">
        {HOUSES.map(h => (
          <div key={h.name} onClick={() => handleSelectObject(h)} className="flex flex-col items-center group cursor-pointer">
            <div className="text-9xl transition-all duration-500 group-hover:scale-125 group-hover:drop-shadow-[0_0_50px_rgba(255,255,255,0.6)] float">
              {h.object}
            </div>
            <div className="mt-6 w-32 h-3 bg-white/10 rounded-full group-hover:bg-yellow-400 transition-colors shadow-lg"></div>
          </div>
        ))}
      </div>
      <div className="fixed bottom-10 left-10 flex gap-6 opacity-20">
        <span className="text-6xl animate-pulse">🕯️</span>
        <span className="text-6xl animate-pulse delay-500">🕯️</span>
      </div>
    </div>
  );
};

