        <span className="text-7xl mb-4 float">📚</span>
        <span className="font-bold bangers tracking-widest text-2xl uppercase">Library</span>
      </div>
      <div className="absolute top-10 right-10 w-52 h-72 bg-red-900/60 backdrop-blur-sm rounded-t-full border-x-4 border-b-4 border-yellow-400 flex flex-col items-center justify-center text-white cursor-pointer hover:bg-red-800 transition-all shadow-2xl" onClick={() => onLocationClick('great_hall')}>
        <span className="text-7xl mb-4 float">🍗</span>
