                   {house.icon}
                 </div>
            )}
          </div>
          <h2 className="text-5xl font-bold bangers text-yellow-400 tracking-widest mb-2 uppercase">{profile.studentName}</h2>
          <p className="text-2xl opacity-70 mb-6 uppercase tracking-widest">{profile.classLevel} | Roll: {profile.rollNumber}</p>
          {!isPreschool && profile.house && (
            <div className={`px-8 py-2 rounded-full font-bold bangers text-2xl tracking-widest ${house?.color || 'bg-gray-700'}`}>House {profile.house}</div>
          )}
        </Card>
        <div className="grid grid-cols-2 gap-6">
          <StatCard icon="✨" label="XP" value={profile.progress.xp.toString()} />
          <StatCard icon="⭐" label="Stars" value={profile.progress.starsEarned.toString()} />
        </div>
        <Button variant="danger" className="w-full py-5 text-2xl uppercase bangers tracking-widest" onClick={onLogout}>Exit World</Button>
      </div>
    </div>
