  <div onClick={onClick} className={`${color} p-12 rounded-[3rem] shadow-2xl flex flex-col items-center justify-center cursor-pointer transform hover:scale-105 transition-all border-4 border-white/20`}>
    <span className="text-9xl mb-6 float">{icon}</span>
    <span className="text-4xl font-bold bangers tracking-widest uppercase">{role}</span>
