          <input required placeholder="Student Name" className="w-full p-5 bg-white/10 border-2 border-white/20 rounded-2xl text-xl outline-none focus:border-yellow-400" onChange={e => setFormData({...formData, studentName: e.target.value})} />
          <div className="flex gap-6">
            <input required placeholder="Section" className="w-full p-5 bg-white/10 border-2 border-white/20 rounded-2xl text-xl outline-none focus:border-yellow-400" onChange={e => setFormData({...formData, section: e.target.value})} />
            <input required placeholder="Roll No" className="w-full p-5 bg-white/10 border-2 border-white/20 rounded-2xl text-xl outline-none focus:border-yellow-400" onChange={e => setFormData({...formData, rollNumber: e.target.value})} />
          </div>
          <Button variant="magical" className="w-full mt-6" onClick={() => {}}>Enter World ✨</Button>
