const PreschoolMap: React.FC<{ onNodeClick: (l: Lesson) => void, profile: any, onAvatarClick: () => void }> = ({ onNodeClick, profile, onAvatarClick }) => {
  const classLevel = profile?.classLevel || 'Preschool';
  const boardKey = 'Common';
  const nodes: Lesson[] = Object.values(SYLLABUS[classLevel]?.[boardKey] || {}).flat() as Lesson[];
  const avatarId = profile?.progress?.currentAvatar;
  const avatar = PRESCHOOL_AVATARS.find(a => a.id === avatarId) || PRESCHOOL_AVATARS[0];

  return (
    <div className="min-h-screen candy-bg p-6 relative overflow-hidden">
      <div className="fixed top-8 left-8 z-50 w-24 h-24 rounded-full border-8 border-white bg-indigo-100 shadow-2xl cursor-pointer hover:scale-110 transition-all overflow-hidden" onClick={onAvatarClick}>
        <img src={avatar.image} className="w-full h-full object-cover" alt="Profile" />
      </div>
      <div className="absolute top-20 right-20 text-8xl opacity-20 float">🍭</div>
      <div className="absolute bottom-40 left-10 text-9xl opacity-20 float">🌈</div>

