      <div className="flex flex-col items-center relative gap-24 mt-20">
        <svg className="absolute top-0 w-full h-[2000px] pointer-events-none" viewBox="0 0 400 2000">
          <path d="M 200 0 Q 350 200 200 400 Q 50 600 200 800 Q 350 1000 200 1200" fill="none" stroke="#f472b6" strokeWidth="25" className="candy-crush-path" strokeLinecap="round" />
        </svg>
        {nodes.map((node, i) => {
          const isLocked = i > (profile?.progress?.lessonsCompleted?.length || 0);
          return (
            <div key={node.id} onClick={() => !isLocked && onNodeClick(node)} className={`z-10 w-32 h-32 rounded-full shadow-[0_15px_30px_rgba(0,0,0,0.1)] flex items-center justify-center text-5xl cursor-pointer transition-all hover:scale-110 ${isLocked ? 'bg-gray-200 border-8 border-white opacity-60' : 'bg-white border-8 border-pink-400 text-pink-500 font-bold'}`}>
              {isLocked ? '🔒' : i+1}
            </div>
          );
        })}
      </div>
    </div>
  );
};

