      <Header title={lesson.title} onBack={onBack} onHome={() => {}} />
      <div className="p-8 max-w-4xl mx-auto">
        <div className="bg-black/50 aspect-video rounded-[3rem] border-4 border-yellow-400/30 overflow-hidden shadow-2xl relative">
          {lesson.videoUrl ? (
            <iframe 
              width="100%" 
              height="100%" 
              src={`${lesson.videoUrl}?autoplay=0&rel=0`} 
              title={lesson.title} 
              frameBorder="0" 
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
              allowFullScreen
