const QuizScreen: React.FC<{ lessonId: string, onComplete: (score: number) => void, onBack: () => void, language: string }> = ({ onComplete, onBack }) => {
  const [q, setQ] = useState(0);
  const [score, setScore] = useState(0);
  const questions = [
    { text: "What is the color of a ripe mango?", options: ["Blue", "Yellow", "Pink"], correct: 1 },
    { text: "Which animal gives us milk?", options: ["Cow", "Lion", "Snake"], correct: 0 }
  ];
  const handleAnswer = (i: number) => {
    if (i === questions[q].correct) setScore(s => s + 1);
    if (q < questions.length - 1) setQ(q + 1);
    else onComplete(score + (i === questions[q].correct ? 1 : 0));
  };
  return (
    <div className="min-h-screen magic-bg p-8 text-white">
      <Header title="Quiz Hall" onBack={onBack} onHome={() => {}} />
      <div className="max-w-2xl mx-auto mt-20">
        <div className="text-center mb-16">
          <span className="text-2xl font-bold bangers tracking-widest text-yellow-400 uppercase">Question {q + 1} of {questions.length}</span>
          <div className="w-full bg-white/10 h-6 rounded-full mt-6 border-2 border-white/10 overflow-hidden">
            <div className="bg-yellow-400 h-full transition-all duration-500" style={{width: `${((q+1)/questions.length)*100}%`}}></div>
          </div>
        </div>
        <Card className="bg-indigo-900 border-yellow-400 p-12 text-center shadow-2xl">
          <h3 className="text-4xl font-bold mb-12">{questions[q].text}</h3>
          <div className="space-y-6">
            {questions[q].options.map((opt, i) => (
              <button key={i} onClick={() => handleAnswer(i)} className="w-full p-6 text-2xl border-4 border-white/10 rounded-3xl hover:bg-yellow-400 hover:text-indigo-900 transition-all font-bold">{opt}</button>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
};

const ChatbotScreen: React.FC<{ chatHistory: any, setChatHistory: any, language: string, onBack: () => void }> = ({ chatHistory, setChatHistory, language, onBack }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  useEffect(() => { scrollRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory]);
  const handleSend = async () => {
    if (!input.trim()) return;
    setChatHistory([...chatHistory, { role: 'user', text: input }]);
    const currentInput = input;
    setInput('');
    setLoading(true);
    const reply = await askMentor(currentInput, language as any);
    setChatHistory((prev: any) => [...prev, { role: 'mentor', text: reply }]);
    setLoading(false);
  };
  return (
    <div className="min-h-screen magic-bg flex flex-col text-white">
      <Header title="Mentor Tower" onBack={onBack} onHome={() => {}} />
      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {chatHistory.map((msg: any, i: number) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-6 rounded-[2rem] text-xl shadow-xl ${msg.role === 'user' ? 'bg-indigo-500 rounded-br-none' : 'bg-white text-indigo-900 rounded-bl-none'}`}>{msg.text}</div>
          </div>
        ))}
        {loading && <div className="text-yellow-400 italic animate-pulse p-4 uppercase">Magical response incoming...</div>}
        <div ref={scrollRef} />
      </div>
      <div className="p-6 bg-white/5 border-t border-white/10 flex gap-4">
        <input value={input} onChange={e => setInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && handleSend()} placeholder="Ask the Mentor..." className="flex-1 p-5 bg-white/10 border-2 border-white/10 rounded-2xl text-xl text-white outline-none focus:border-yellow-400 shadow-inner" />
        <Button onClick={handleSend} className="px-8 py-5">✨</Button>
      </div>
    </div>
  );
};

const StudentDashboard: React.FC<{ profile: UserProfile | null, onBack: () => void, onLogout: () => void }> = ({ profile, onBack, onLogout }) => {
  if (!profile) return null;
  const isPreschool = profile.classLevel === 'Preschool';
  const avatarPool = isPreschool ? PRESCHOOL_AVATARS : CLASS_1_5_AVATARS;
  const avatarImg = avatarPool.find(a => a.id === profile.progress.currentAvatar)?.image || avatarPool[0].image;
  const house = HOUSES.find(h => h.name === profile.house);

  return (
    <div className="min-h-screen magic-bg text-white">
      <Header title="Dashboard" onBack={onBack} onHome={goBack} />
      <div className="p-8 max-w-2xl mx-auto space-y-8">
        <Card className="bg-indigo-900/50 border-yellow-400 p-12 text-center text-white shadow-2xl">
          <div className={`w-40 h-40 rounded-full border-8 mb-6 overflow-hidden mx-auto shadow-2xl relative ${house?.color.replace('bg-', 'border-') || 'border-yellow-400'}`}>
            <img src={avatarImg} className="w-full h-full object-cover" alt="Profile" />
            {!isPreschool && house && (
                 <div className={`absolute top-0 right-0 w-10 h-10 rounded-full border-2 border-white ${house.color} flex items-center justify-center text-lg`}>
                   {house.icon}
                 </div>
            )}
          </div>
          <h2 className="text-5xl font-bold bangers text-yellow-400 tracking-widest mb-2 uppercase">{profile.studentName}</h2>
          <p className="text-2xl opacity-70 mb-6 uppercase tracking-widest">{profile.classLevel} | Roll: {profile.rollNumber}</p>
          {!isPreschool && profile.house && (
            <div className={`px-8 py-2 rounded-full font-bold bangers text-2xl tracking-widest ${house?.color || 'bg-gray-700'}`}>House {profile.house}</div>
          )}
        </Card>
        <div className="grid grid-cols-2 gap-6">
          <StatCard icon="✨" label="XP" value={profile.progress.xp.toString()} />
          <StatCard icon="⭐" label="Stars" value={profile.progress.starsEarned.toString()} />
        </div>
        <Button variant="danger" className="w-full py-5 text-2xl uppercase bangers tracking-widest shadow-2xl" onClick={onLogout}>Exit World</Button>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ icon: string, label: string, value: string }> = ({ icon, label, value }) => (
