                   {house.icon}
                 </div>
               )}
            </div>
            <span className="text-2xl font-bold text-indigo-900 bangers uppercase tracking-widest">{a.name}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

const AIAvatarMaker: React.FC<{ onBack: () => void, onGenerate: (p: string) => void, isGenerating: boolean, generatedUrl: string | null, onSave: (url: string) => void }> = ({ onBack, onGenerate, isGenerating, generatedUrl, onSave }) => {
  const [prompt, setPrompt] = useState('');
  return (
    <div className="min-h-screen magic-bg p-8 text-white flex flex-col items-center">
      <Header title="AI Avatar Maker" onBack={onBack} onHome={onBack} />
      <div className="max-w-2xl w-full mt-12">
        <Card className="bg-indigo-900/60 border-yellow-400 p-10 text-center shadow-2xl">
          <h2 className="text-4xl font-bold bangers text-yellow-400 mb-8 uppercase tracking-widest">Create Magic Avatar</h2>
          <p className="text-xl mb-8 opacity-80">Type what you want your buddy to look like! (e.g., "A blue robot with wings", "A magical panda")</p>

          <input 
            value={prompt} 
            onChange={e => setPrompt(e.target.value)}
            className="w-full p-6 bg-white/10 border-4 border-white/20 rounded-3xl text-2xl text-white outline-none focus:border-yellow-400 mb-8 placeholder:text-white/30"
            placeholder="Describe your buddy..."
          />

          <Button 
            variant="magical" 
            className="w-full py-6 text-3xl bangers uppercase" 
            onClick={() => onGenerate(prompt)}
            disabled={isGenerating || !prompt.trim()}
          >
            {isGenerating ? 'Casting Spell...' : 'Generate Magic ✨'}
          </Button>

          {isGenerating && (
            <div className="mt-12 flex flex-col items-center">
              <div className="w-24 h-24 border-8 border-yellow-400 border-t-transparent rounded-full animate-spin"></div>
              <p className="mt-6 text-2xl bangers tracking-widest animate-pulse">CREATING MAGIC...</p>
            </div>
          )}

          {generatedUrl && !isGenerating && (
            <div className="mt-12 animate-flag">
              <div className="w-64 h-64 mx-auto rounded-[3rem] overflow-hidden border-8 border-yellow-400 shadow-[0_0_50px_rgba(251,191,36,0.4)]">
                <img src={generatedUrl} className="w-full h-full object-cover" alt="Generated" />
              </div>
              <Button variant="primary" className="mt-8 px-12 py-4 text-2xl bangers uppercase" onClick={() => onSave(generatedUrl)}>Use This Buddy!</Button>
            </div>
          )}
        </Card>
      </div>
    </div>
  );
};

const PreschoolMap: React.FC<{ onNodeClick: (l: Lesson) => void, profile: any, onAvatarClick: () => void }> = ({ onNodeClick, profile, onAvatarClick }) => {
  const classLevel = profile?.classLevel || 'Preschool';
  const boardKey = 'Common';
  const nodes: Lesson[] = Object.values(SYLLABUS[classLevel]?.[boardKey] || {}).flat() as Lesson[];
  const avatarId = profile?.progress?.currentAvatar;
  const avatar = avatarId === 'custom_ai' ? { image: profile.customAvatarUrl || '' } : (PRESCHOOL_AVATARS.find(a => a.id === avatarId) || PRESCHOOL_AVATARS[0]);

  return (
    <div className="min-h-screen candy-bg p-6 relative overflow-hidden">
      <div className="fixed top-8 left-8 z-50 w-24 h-24 rounded-full border-8 border-white bg-indigo-100 shadow-2xl cursor-pointer hover:scale-110 transition-all overflow-hidden" onClick={onAvatarClick}>
        <img src={avatar.image} className="w-full h-full object-cover" alt="Profile" />
      </div>
      <div className="absolute top-20 right-20 text-8xl opacity-20 float">🍭</div>
      <div className="absolute bottom-40 left-10 text-9xl opacity-20 float">🌈</div>

      <h2 className="text-7xl font-bold text-pink-500 text-center mt-6 bangers tracking-[0.2em] drop-shadow-lg uppercase">CANDY WORLD</h2>
      <div className="flex flex-col items-center relative gap-24 mt-20">
        <svg className="absolute top-0 w-full h-[2000px] pointer-events-none" viewBox="0 0 400 2000">
          <path d="M 200 0 Q 350 200 200 400 Q 50 600 200 800 Q 350 1000 200 1200" fill="none" stroke="#f472b6" strokeWidth="25" className="candy-crush-path" strokeLinecap="round" />
        </svg>
        {nodes.map((node, i) => {
          const isLocked = i > (profile?.progress?.lessonsCompleted?.length || 0);
          return (
            <div key={node.id} onClick={() => !isLocked && onNodeClick(node)} className={`z-10 w-32 h-32 rounded-full shadow-[0_15px_30px_rgba(0,0,0,0.1)] flex items-center justify-center text-5xl cursor-pointer transition-all hover:scale-110 ${isLocked ? 'bg-gray-200 border-8 border-white opacity-60' : 'bg-white border-8 border-pink-400 text-pink-500 font-bold'}`}>
              {isLocked ? '🔒' : i+1}
            </div>
          );
        })}
      </div>
    </div>
  );
};

