import { GoogleGenAI } from "@google/genai";

export async function askMentor(prompt: string, language: 'English' | 'Telugu' = 'English') {
  try {
    // Fix: Instantiate GoogleGenAI right before making an API call to ensure it uses the most up-to-date API key
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: `You are a friendly magical mentor named Sparky for a rural school student. 
        Explain concepts simply using rural real-life examples. 
        Respond in ${language}. If Telugu, use simple words. 
        Be encouraging and brief. No long text.`,
      }
    });
    // The .text property directly returns the generated text.
    return response.text || "I'm a bit sleepy, try asking again!";
  } catch (error) {
    console.error("AI Error:", error);
    return "The magic is recharging! Please try again later.";
  }
}

