const PreschoolMap: React.FC<{ onNodeClick: (l: Lesson) => void, profile: any, onAvatarClick: () => void }> = ({ onNodeClick, profile, onAvatarClick }) => {
  const classLevel = profile?.classLevel || 'Preschool';
  const boardKey = 'Common';
  const nodes: Lesson[] = Object.values(SYLLABUS[classLevel]?.[boardKey] || {}).flat() as Lesson[];
  const avatarId = profile?.progress?.currentAvatar;
  const avatar = avatarId === 'custom_ai' ? { image: profile.customAvatarUrl || '' } : (PRESCHOOL_AVATARS.find(a => a.id === avatarId) || PRESCHOOL_AVATARS[0]);

  return (
    <div className="min-h-screen candy-bg relative overflow-y-auto">
      <div className="fixed top-20 left-4 z-40 w-20 h-20 rounded-full border-4 border-white bg-indigo-100 shadow-xl cursor-pointer hover:scale-110 transition-all overflow-hidden" onClick={onAvatarClick}>
        <img src={avatar.image} className="w-full h-full object-cover" alt="Profile" />
      </div>

      <h2 className="text-5xl font-bold text-pink-500 text-center py-10 bangers tracking-widest drop-shadow-md uppercase">CANDY PATH</h2>
      <div className="flex flex-col items-center relative gap-20 pb-32">
        <svg className="absolute top-0 w-full h-full min-h-[1000px] pointer-events-none" viewBox="0 0 400 1000" preserveAspectRatio="none">
          <path d="M 200 0 Q 300 200 200 400 Q 100 600 200 800 Q 300 1000 200 1200" fill="none" stroke="#f472b6" strokeWidth="20" className="candy-crush-path opacity-40" strokeLinecap="round" />
        </svg>
        {nodes.map((node, i) => {
          const isLocked = i > (profile?.progress?.lessonsCompleted?.length || 0);
          return (
            <div key={node.id} onClick={() => !isLocked && onNodeClick(node)} className={`z-10 w-24 h-24 rounded-full shadow-lg flex items-center justify-center text-4xl cursor-pointer transition-all hover:scale-110 ${isLocked ? 'bg-gray-200 border-4 border-white opacity-60' : 'bg-white border-6 border-pink-400 text-pink-500 font-bold'}`}>
              {isLocked ? '🔒' : i+1}
            </div>
          );
        })}
      </div>
    </div>
  );
};

