const QuizScreen: React.FC<{ lessonId: string, onComplete: (score: number) => void, onBack: () => void, onHome: () => void, language: string }> = ({ onComplete, onBack, onHome }) => {
  const [q, setQ] = useState(0);
  const [score, setScore] = useState(0);
  const questions = [
    { text: "What is the color of a ripe mango?", options: ["Blue", "Yellow", "Pink"], correct: 1 },
    { text: "Which animal gives us milk?", options: ["Cow", "Lion", "Snake"], correct: 0 }
  ];
  const handleAnswer = (i: number) => {
    if (i === questions[q].correct) setScore(s => s + 1);
    if (q < questions.length - 1) setQ(q + 1);
    else onComplete(score + (i === questions[q].correct ? 1 : 0));
  };
  return (
    <div className="min-h-screen magic-bg p-0 text-white flex flex-col">
      <Header title="Quiz Hall" onBack={onBack} onHome={onHome} />
      <div className="flex-1 overflow-y-auto p-4 md:p-8 max-w-2xl mx-auto w-full">
        <div className="text-center my-8">
          <span className="text-2xl font-bold bangers tracking-widest text-yellow-400 uppercase">Question {q + 1} of {questions.length}</span>
          <div className="w-full bg-white/10 h-6 rounded-full mt-6 border-2 border-white/10 overflow-hidden">
            <div className="bg-yellow-400 h-full transition-all duration-500" style={{width: `${((q+1)/questions.length)*100}%`}}></div>
          </div>
        </div>
        <Card className="bg-indigo-950 border-yellow-400 p-8 md:p-12 text-center shadow-2xl text-white">
          <h3 className="text-3xl md:text-4xl font-bold mb-12 text-white leading-tight">{questions[q].text}</h3>
          <div className="space-y-6">
            {questions[q].options.map((opt, i) => (
              <button key={i} onClick={() => handleAnswer(i)} className="w-full p-6 text-2xl border-4 border-white/20 rounded-3xl hover:bg-yellow-400 hover:text-indigo-950 transition-all font-bold text-white shadow-lg bg-white/5 active:scale-95">{opt}</button>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
};

const ChatbotScreen: React.FC<{ chatHistory: any, setChatHistory: any, language: string, onBack: () => void, onHome: () => void }> = ({ chatHistory, setChatHistory, language, onBack, onHome }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  useEffect(() => { scrollRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const currentInput = input;
    setChatHistory([...chatHistory, { role: 'user', text: currentInput }]);
    setInput('');
    setLoading(true);
    const reply = await askMentor(currentInput, language as any);
    setChatHistory((prev: any) => [...prev, { role: 'mentor', text: reply }]);
    setLoading(false);
  };

  return (
    <div className="min-h-screen magic-bg flex flex-col text-white">
      <Header title="Mentor Tower" onBack={onBack} onHome={onHome} />
      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {chatHistory.map((msg: any, i: number) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-5 rounded-[2rem] text-xl shadow-xl ${msg.role === 'user' ? 'bg-indigo-600 rounded-br-none border-2 border-white/20' : 'bg-white text-indigo-950 rounded-bl-none font-medium'}`}>{msg.text}</div>
          </div>
        ))}
        {loading && <div className="text-yellow-400 italic animate-pulse p-4 bangers tracking-widest uppercase">Sparky is thinking...</div>}
        <div ref={scrollRef} />
      </div>
      <div className="p-4 bg-white/10 backdrop-blur-md border-t border-white/10 flex gap-4">
        <input value={input} onChange={e => setInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && handleSend()} placeholder="Ask Sparky something..." className="flex-1 p-5 bg-indigo-950/80 border-2 border-white/30 rounded-2xl text-xl text-white outline-none focus:border-yellow-400 shadow-inner placeholder:text-white/40" />
        <Button onClick={handleSend} className="px-6 py-5 text-2xl">✨</Button>
      </div>
    </div>
  );
};

const StudentDashboard: React.FC<{ profile: any | null, onBack: () => void, onHome: () => void, onLogout: () => void }> = ({ profile, onBack, onHome, onLogout }) => {
