          <div className="flex flex-col gap-4">
             <Button variant="primary" className="py-4 text-2xl uppercase bangers" onClick={() => onComplete(selectedHouse!.name as HouseName)}>Enter School 🏰</Button>
             <Button variant="secondary" className="py-2 text-xl" onClick={onBack}>Change Grade 🪄</Button>
          </div>
        </div>
      </div>
    );
  }

  if (phase === 'confirmation') {
    return (
      <div className="min-h-screen bg-indigo-950 flex flex-col items-center justify-center text-white p-10">
        <div className={`w-64 h-64 md:w-72 md:h-72 rounded-full ${selectedHouse?.color} flex items-center justify-center text-8xl md:text-9xl shadow-[0_0_100px_rgba(255,255,255,0.4)] animate-pulse cursor-pointer hover:scale-110 transition-transform`} onClick={handleConfirm}>
