  if (phase === 'path') {
    return (
      <div className="min-h-screen bg-indigo-950 flex flex-col items-center justify-center text-white p-10 overflow-hidden text-center">
        <div className={`w-4 h-screen bg-gradient-to-b ${selectedHouse?.pathColor} absolute top-0 shadow-[0_0_50px_rgba(255,255,255,0.2)]`}></div>
