  return (
    <div className="min-h-screen bg-indigo-950 flex flex-col items-center justify-center p-6 text-center text-white overflow-hidden">
      <h2 className="text-4xl md:text-5xl font-bold mb-6 bangers tracking-widest text-yellow-400 uppercase tracking-[0.2em]">Sorting Ceremony</h2>
