        <h2 className="text-4xl md:text-5xl font-bold text-center mb-10 bangers text-yellow-400 uppercase tracking-widest leading-tight">
          {profile?.role || 'Student'} Magic Entry
        </h2>
        <form onSubmit={(e) => { e.preventDefault(); setProfile({ ...formData, role: profile.role || 'Student', progress: { lessonsCompleted: [], quizzesCompleted: [], gamesPlayed: [], starsEarned: 0, xp: 0, housePoints: 0, unlockedAvatars: [], currentAvatar: '' } }); onComplete(); }} className="space-y-6">
          <div className="space-y-2">
            <label className="text-yellow-200 font-bold uppercase tracking-widest text-sm block">Magical School Name</label>
            <input required placeholder="Enter School Name" className="w-full p-5 bg-white/5 border-2 border-white/20 rounded-2xl text-xl text-white placeholder:text-white/20 outline-none focus:border-yellow-400 focus:bg-white/10 transition-all" onChange={e => setFormData({...formData, schoolName: e.target.value})} />
          </div>
          <div className="space-y-2">
            <label className="text-yellow-200 font-bold uppercase tracking-widest text-sm block">Student Full Name</label>
            <input required placeholder="Enter Your Name" className="w-full p-5 bg-white/5 border-2 border-white/20 rounded-2xl text-xl text-white placeholder:text-white/20 outline-none focus:border-yellow-400 focus:bg-white/10 transition-all" onChange={e => setFormData({...formData, studentName: e.target.value})} />
          </div>
          <div className="space-y-2">
            <label className="text-yellow-200 font-bold uppercase tracking-widest text-sm block">Roll Number</label>
            <input required placeholder="Enter Roll Number" className="w-full p-5 bg-white/5 border-2 border-white/20 rounded-2xl text-xl text-white placeholder:text-white/20 outline-none focus:border-yellow-400 focus:bg-white/10 transition-all" onChange={e => setFormData({...formData, rollNumber: e.target.value})} />
          </div>
          <Button variant="magical" className="w-full mt-6 py-6 text-2xl uppercase bangers" onClick={() => {}}>Open the Magic Gates ✨</Button>
        </form>
      </div>
    </div>
  );
};

const ClassSelectionScreen: React.FC<{ onSelect: (lvl: ClassLevel) => void }> = ({ onSelect }) => (
  <div className="h-full magic-bg p-6 flex flex-col items-center justify-center text-center text-white overflow-y-auto">
    <h2 className="text-6xl font-bold text-yellow-400 mb-12 bangers tracking-widest uppercase">Which Grade?</h2>
    <div className="grid grid-cols-2 md:grid-cols-3 gap-6 w-full max-w-5xl">
      {['Preschool', 'Class 1', 'Class 2', 'Class 3', 'Class 4', 'Class 5'].map(lvl => (
        <div key={lvl} onClick={() => onSelect(lvl as ClassLevel)} className="bg-white/10 p-8 md:p-12 rounded-[2rem] border-4 border-white/10 cursor-pointer hover:bg-white/20 hover:border-yellow-400 transition-all group shadow-xl">
          <span className="text-3xl font-bold bangers tracking-wider group-hover:text-yellow-400 uppercase text-white">{lvl}</span>
        </div>
      ))}
    </div>
  </div>
);

const SortingCeremony: React.FC<{ onComplete: (h: HouseName) => void, language: string, onBack: () => void }> = ({ onComplete, language, onBack }) => {
  const [phase, setPhase] = useState<'attraction' | 'path' | 'confirmation' | 'reveal'>('attraction');
  const [selectedHouse, setSelectedHouse] = useState<typeof HOUSES[0] | null>(null);

  const handleSelectObject = (house: typeof HOUSES[0]) => {
    setSelectedHouse(house);
    setPhase('path');
    setTimeout(() => setPhase('confirmation'), 3000);
  };

  const handleConfirm = () => {
    setPhase('reveal');
    window.speechSynthesis.cancel();
    const msg = new SpeechSynthesisUtterance();
    msg.text = language === 'Telugu' ? selectedHouse!.audioTe : selectedHouse!.audioEn;
    msg.lang = language === 'Telugu' ? 'te-IN' : 'en-US';
    window.speechSynthesis.speak(msg);
  };

  if (phase === 'reveal') {
    return (
      <div className={`h-full ${selectedHouse?.color} flex flex-col items-center justify-center text-white overflow-hidden p-10`}>
        <div className="animate-flag w-64 h-[28rem] bg-white/20 backdrop-blur-md rounded-b-[2rem] border-x-8 border-b-8 border-yellow-400/50 flex flex-col items-center p-10 shadow-2xl">
          <div className="text-[10rem] mb-12 drop-shadow-2xl">{selectedHouse?.icon}</div>
          <h1 className="bangers text-6xl tracking-[0.3em] uppercase">{selectedHouse?.name}</h1>
        </div>
        <div className="mt-16 text-center space-y-6">
          <p className="text-3xl md:text-4xl font-bold animate-pulse px-4">{language === 'Telugu' ? selectedHouse?.audioTe : `Welcome to ${selectedHouse?.name}!`}</p>
          <div className="flex flex-col gap-4">
             <Button variant="primary" className="py-4 text-2xl uppercase bangers" onClick={() => onComplete(selectedHouse!.name as HouseName)}>Enter School 🏰</Button>
             <Button variant="secondary" className="py-2 text-xl" onClick={onBack}>Change Grade 🪄</Button>
          </div>
        </div>
      </div>
    );
  }

  if (phase === 'confirmation') {
    return (
      <div className="h-full bg-indigo-950 flex flex-col items-center justify-center text-white p-10">
        <div className={`w-64 h-64 md:w-72 md:h-72 rounded-full ${selectedHouse?.color} flex items-center justify-center text-8xl md:text-9xl shadow-[0_0_100px_rgba(255,255,255,0.4)] animate-pulse cursor-pointer hover:scale-110 transition-transform`} onClick={handleConfirm}>
          {selectedHouse?.icon}
        </div>
