const QuizScreen: React.FC<{ lessonId: string, onComplete: (score: number) => void, onBack: () => void, onHome: () => void, language: string }> = ({ onComplete, onBack, onHome }) => {
  const [q, setQ] = useState(0);
  const [score, setScore] = useState(0);
  const questions = [
    { text: "What is the color of a ripe mango?", options: ["Blue", "Yellow", "Pink"], correct: 1 },
    { text: "Which animal gives us milk?", options: ["Cow", "Lion", "Snake"], correct: 0 }
  ];
  const handleAnswer = (i: number) => {
    if (i === questions[q].correct) setScore(s => s + 1);
    if (q < questions.length - 1) setQ(q + 1);
    else onComplete(score + (i === questions[q].correct ? 1 : 0));
  };
  return (
    <div className="h-full magic-bg text-white flex flex-col">
      <Header title="Quiz Hall" onBack={onBack} onHome={onHome} />
      <div className="flex-1 overflow-y-auto p-6 md:p-12">
        <div className="max-w-3xl mx-auto w-full">
          <div className="text-center my-10">
            <span className="text-3xl font-bold bangers tracking-widest text-yellow-400 uppercase">Question {q + 1} of {questions.length}</span>
            <div className="w-full bg-white/10 h-8 rounded-full mt-8 border-2 border-white/20 overflow-hidden shadow-inner">
              <div className="bg-yellow-400 h-full transition-all duration-700 shadow-[0_0_20px_rgba(250,204,21,0.5)]" style={{width: `${((q+1)/questions.length)*100}%`}}></div>
            </div>
          </div>
          <div className="bg-slate-900 border-4 border-yellow-400 p-10 md:p-16 text-center rounded-[3rem] shadow-[0_0_60px_rgba(0,0,0,0.6)]">
            <h3 className="text-3xl md:text-5xl font-bold mb-16 text-white leading-snug drop-shadow-lg">{questions[q].text}</h3>
            <div className="space-y-8">
              {questions[q].options.map((opt, i) => (
                <button 
                  key={i} 
                  onClick={() => handleAnswer(i)} 
                  className="w-full p-8 text-2xl md:text-4xl border-4 border-white/20 rounded-[2rem] hover:bg-yellow-400 hover:text-indigo-950 hover:border-white transition-all font-bold text-white shadow-xl bg-white/5 active:scale-95 group"
                >
                  <span className="group-hover:text-indigo-950">{opt}</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const ChatbotScreen: React.FC<{ chatHistory: any, setChatHistory: any, language: string, onBack: () => void, onHome: () => void }> = ({ chatHistory, setChatHistory, language, onBack, onHome }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  useEffect(() => { scrollRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory]);

  const handleSend = async () => {
    if (!input.trim()) return;
    const currentInput = input;
    setChatHistory([...chatHistory, { role: 'user', text: currentInput }]);
    setInput('');
    setLoading(true);
    const reply = await askMentor(currentInput, language as any);
    setChatHistory((prev: any) => [...prev, { role: 'mentor', text: reply }]);
    setLoading(false);
  };

  return (
    <div className="h-full magic-bg flex flex-col text-white">
      <Header title="Mentor Tower" onBack={onBack} onHome={onHome} />
      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {chatHistory.map((msg: any, i: number) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-6 rounded-[2.5rem] text-xl shadow-2xl leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 rounded-br-none border-2 border-white/20 text-white shadow-[0_0_15px_rgba(79,70,229,0.3)]' : 'bg-white text-indigo-950 rounded-bl-none font-medium shadow-[0_0_15px_rgba(255,255,255,0.2)]'}`}>{msg.text}</div>
          </div>
        ))}
        {loading && <div className="text-yellow-400 italic animate-pulse p-6 bangers tracking-widest uppercase text-2xl text-center">Sparky is summoning knowledge...</div>}
        <div ref={scrollRef} />
      </div>
      <div className="p-6 bg-slate-900/90 backdrop-blur-md border-t-4 border-yellow-400 flex gap-4">
        <input value={input} onChange={e => setInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && handleSend()} placeholder="Ask your Magical Mentor..." className="flex-1 p-6 bg-white/5 border-2 border-white/20 rounded-3xl text-2xl text-white outline-none focus:border-yellow-400 shadow-inner placeholder:text-white/20" />
        <Button onClick={handleSend} className="px-10 py-6 text-3xl">✨</Button>
      </div>
    </div>
  );
};

