import React, { useState, useEffect, useCallback, useRef } from 'react';
import { UserProfile, UserProgress, Role, Language, ClassLevel, Board, HouseName, Lesson, Avatar } from './types';
import { SYLLABUS, HOUSES, PRESCHOOL_AVATARS, CLASS_1_5_AVATARS } from './constants';
import { Button, Card, Header, AudioPlayer } from './components/UI';
import { askMentor } from './services/geminiService';
import { GoogleGenAI } from "@google/genai";

const App: React.FC = () => {
  const [screen, setScreen] = useState<string>('splash');
  const [history, setHistory] = useState<string[]>(['splash']);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [currentLesson, setCurrentLesson] = useState<Lesson | null>(null);
  const [chatHistory, setChatHistory] = useState<{ role: string, text: string }[]>([]);
  const [isGeneratingAvatar, setIsGeneratingAvatar] = useState(false);
  const [generatedAvatarUrl, setGeneratedAvatarUrl] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('rural_learn_v2');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setProfile(parsed);
        if (parsed.customAvatarUrl) {
          setGeneratedAvatarUrl(parsed.customAvatarUrl);
        }
      } catch (e) {
        console.error("Storage corrupt", e);
      }
    }
  }, []);

  useEffect(() => {
    if (profile) localStorage.setItem('rural_learn_v2', JSON.stringify(profile));
  }, [profile]);

  const navigateTo = (newScreen: string) => {
    setHistory(prev => [...prev, screen]);
    setScreen(newScreen);
  };

  const goBack = () => {
    if (history.length > 1) {
      const last = history[history.length - 1];
      setHistory(prev => prev.slice(0, -1));
      setScreen(last);
    }
  };

  const goHome = () => {
    if (profile?.classLevel === 'Preschool') setScreen('preschool_map');
    else setScreen('hogwarts_map');
    setHistory(['splash']);
  };

  const handleGenerateAvatar = async (prompt: string) => {
    setIsGeneratingAvatar(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: `A cute, friendly cartoon 2D avatar of ${prompt} for a kid's educational app. Vibrant colors, simple shapes, high quality.`,
        config: {
          numberOfImages: 1,
          aspectRatio: '1:1',
        },
      });

      if (response.generatedImages && response.generatedImages.length > 0) {
        const base64 = response.generatedImages[0].image.imageBytes;
        setGeneratedAvatarUrl(`data:image/png;base64,${base64}`);
      }
    } catch (error) {
      console.error("Failed to generate avatar:", error);
      alert("Magic failed! Try a simpler prompt.");
    } finally {
      setIsGeneratingAvatar(false);
    }
  };

  // --- Screens ---

  if (screen === 'splash') {
    return (
      <div className="h-full flex flex-col items-center justify-center magic-bg text-white p-10 text-center overflow-hidden cursor-pointer" onClick={() => navigateTo('role_selection')}>
        <div className="float text-9xl mb-8 drop-shadow-[0_0_20px_rgba(255,255,255,0.5)]">🎒</div>
        <h1 className="bangers text-7xl md:text-8xl mb-4 tracking-widest text-yellow-400 drop-shadow-lg uppercase">Rural Learn</h1>
        <p className="text-2xl md:text-3xl font-medium animate-pulse opacity-80">Tap to Enter the Magic...</p>
      </div>
    );
  }

  if (screen === 'role_selection') {
    return (
      <div className="h-full magic-bg flex flex-col items-center justify-center p-6 text-white overflow-y-auto">
        <h2 className="text-5xl font-bold mb-12 bangers tracking-widest text-yellow-400 uppercase text-center">Who are you?</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 w-full max-w-5xl">
          <RoleCard role="Student" icon="🧒" color="bg-blue-500" onClick={() => { setProfile(p => ({ ...p, role: 'Student' } as UserProfile)); navigateTo('login'); }} />
          <RoleCard role="Teacher" icon="👩‍🏫" color="bg-emerald-500" onClick={() => { setProfile(p => ({ ...p, role: 'Teacher' } as UserProfile)); navigateTo('login'); }} />
          <RoleCard role="Parent" icon="👨‍👩‍👧" color="bg-purple-500" onClick={() => { setProfile(p => ({ ...p, role: 'Parent' } as UserProfile)); navigateTo('login'); }} />
        </div>
      </div>
    );
  }

  if (screen === 'login') {
    return <LoginScreen profile={profile} setProfile={setProfile} onComplete={() => navigateTo('language_selection')} />;
  }

  if (screen === 'language_selection') {
    return (
      <div className="h-full magic-bg flex flex-col items-center justify-center p-6 text-white">
        <h2 className="text-5xl font-bold mb-12 bangers text-yellow-400 uppercase text-center">Choose Language</h2>
        <div className="flex flex-col md:flex-row gap-8">
          <Button variant="magical" onClick={() => { setProfile(p => ({ ...p, language: 'English' } as UserProfile)); navigateTo('class_selection'); }} className="px-12 py-6 text-2xl">English 🇬🇧</Button>
          <Button variant="magical" onClick={() => { setProfile(p => ({ ...p, language: 'Telugu' } as UserProfile)); navigateTo('class_selection'); }} className="px-12 py-6 text-2xl">తెలుగు 🇮🇳</Button>
        </div>
      </div>
    );
  }

  if (screen === 'class_selection') {
    return <ClassSelectionScreen onSelect={(lvl) => {
      setProfile(p => ({ ...p, classLevel: lvl } as UserProfile));
      if (lvl === 'Preschool') navigateTo('preschool_avatar_selection');
      else navigateTo('board_selection');
    }} />;
  }

  if (screen === 'preschool_avatar_selection') {
    return <AvatarSelectionScreen pool={PRESCHOOL_AVATARS} onSelect={(id) => {
      setProfile(p => ({ ...p, progress: { ...p?.progress, currentAvatar: id, unlockedAvatars: [id] } } as UserProfile));
      navigateTo('preschool_map');
    }} profile={profile!} isPreschool={true} onBack={goBack} onCustom={() => navigateTo('ai_avatar_maker')} />;
  }

  if (screen === 'board_selection') {
    return (
      <div className="h-full magic-bg flex flex-col items-center justify-center p-6 text-white">
        <h2 className="text-5xl font-bold mb-12 bangers text-yellow-400 uppercase text-center">Select Board</h2>
        <div className="flex flex-col gap-8 w-full max-w-sm">
          <Button variant="magical" onClick={() => { setProfile(p => ({ ...p, board: 'CBSE' } as UserProfile)); navigateTo('sorting_ceremony'); }}>CBSE</Button>
          <Button variant="magical" onClick={() => { setProfile(p => ({ ...p, board: 'Telangana State Board' } as UserProfile)); navigateTo('sorting_ceremony'); }}>Telangana Board</Button>
        </div>
      </div>
    );
  }

  if (screen === 'sorting_ceremony') {
    return <SortingCeremony language={profile?.language || 'English'} onComplete={(house) => {
      setProfile(p => ({ ...p, house } as UserProfile));
      navigateTo('class_avatar_selection');
    }} onBack={() => navigateTo('class_selection')} />;
  }

  if (screen === 'class_avatar_selection') {
    return <AvatarSelectionScreen pool={CLASS_1_5_AVATARS} onSelect={(id) => {
      setProfile(p => ({ ...p, progress: { ...p?.progress, currentAvatar: id, unlockedAvatars: [id] } } as UserProfile));
      navigateTo('hogwarts_map');
    }} profile={profile!} isPreschool={false} onBack={goBack} onCustom={() => navigateTo('ai_avatar_maker')} />;
  }

  if (screen === 'ai_avatar_maker') {
    return (
      <AIAvatarMaker 
        onBack={goBack} 
        onGenerate={handleGenerateAvatar} 
        isGenerating={isGeneratingAvatar} 
        generatedUrl={generatedAvatarUrl} 
        onSave={(url) => {
          setProfile(p => ({ 
            ...p, 
            customAvatarUrl: url,
            progress: { 
              ...p?.progress, 
              currentAvatar: 'custom_ai', 
              unlockedAvatars: [...(p?.progress.unlockedAvatars || []), 'custom_ai'] 
            } 
          } as UserProfile));
          goHome();
        }}
      />
    );
  }

  if (screen === 'preschool_map') {
    return <PreschoolMap onNodeClick={(lesson) => { setCurrentLesson(lesson); navigateTo('lesson_player'); }} profile={profile} onAvatarClick={() => navigateTo('student_dashboard')} />;
  }

  if (screen === 'hogwarts_map') return <HogwartsMap onLocationClick={(loc) => navigateTo(loc)} profile={profile} />;

  if (screen === 'library') {
    const classLevel = profile?.classLevel || 'Class 1';
    const boardKey = profile?.board || 'Common';
    const subjects = SYLLABUS[classLevel]?.[boardKey] || {};

    return (
      <div className="h-full magic-bg p-0 text-white flex flex-col">
        <Header title="Wisdom Well" onBack={goBack} onHome={goHome} />
        <div className="flex-1 overflow-y-auto p-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-5xl mx-auto w-full">
            {Object.entries(subjects).length > 0 ? (
              Object.entries(subjects).map(([subject, lessons]) => (
                <div key={subject} className="bg-white/5 p-6 rounded-3xl border border-white/10 h-fit">
                  <h3 className="text-3xl font-bold text-yellow-400 mb-6 bangers tracking-widest uppercase">{subject}</h3>
                  <div className="space-y-4">
                    {(lessons as Lesson[]).map(l => (
                      <div key={l.id} className="p-4 bg-white/10 rounded-2xl cursor-pointer hover:bg-white/20 transition-colors flex justify-between items-center" onClick={() => { setCurrentLesson(l); navigateTo('lesson_player'); }}>
                        <span className="text-xl font-medium">{l.title}</span>
                        {profile?.progress?.lessonsCompleted?.includes(l.id) && <span className="text-2xl">✅</span>}
                      </div>
                    ))}
                  </div>
                </div>
              ))
            ) : (
              <div className="col-span-full text-center p-10">
                <p className="text-2xl opacity-60">No magic found in this well yet!</p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  if (screen === 'lesson_player') {
    return <LessonPlayer lesson={currentLesson} onComplete={() => navigateTo('quiz')} onBack={goBack} onHome={goHome} profile={profile} />;
  }

  if (screen === 'quiz') {
    return <QuizScreen lessonId={currentLesson?.id || ''} onComplete={(score) => {
      setProfile(p => {
        if (!p || !currentLesson) return null;
        return { ...p, progress: { ...p.progress, quizzesCompleted: [...p.progress.quizzesCompleted, currentLesson.id], starsEarned: p.progress.starsEarned + score, housePoints: p.progress.housePoints + (score * 10) } };
      });
      navigateTo('game');
    }} onBack={goBack} onHome={goHome} language={profile?.language || 'English'} />;
  }

  if (screen === 'game') {
    return (
      <div className="h-full magic-bg flex flex-col items-center justify-center p-6 text-center text-white">
        <h2 className="text-6xl font-bold text-yellow-400 mb-10 bangers tracking-widest uppercase text-center">Spell-Play Fields!</h2>
        <Card className="max-w-md w-full p-10 bg-indigo-900 border-yellow-400 shadow-2xl">
          <div className="text-8xl mb-8 float">🎮</div>
          <p className="text-2xl mb-10 text-white font-medium">Win the magic challenge for {currentLesson?.title}!</p>
          <Button variant="magical" onClick={() => {
            setProfile(p => {
              if (!p || !currentLesson) return null;
              return { ...p, progress: { ...p.progress, gamesPlayed: [...p.progress.gamesPlayed, currentLesson.id], xp: p.progress.xp + 100 } };
            });
            goHome();
          }}>Play & Win!</Button>
        </Card>
      </div>
    );
  }

  if (screen === 'student_dashboard') {
    return <StudentDashboard profile={profile} onBack={goBack} onHome={goHome} onLogout={() => { localStorage.removeItem('rural_learn_v2'); setProfile(null); setScreen('splash'); }} />;
  }

  if (screen === 'chatbot_tower') return <ChatbotScreen chatHistory={chatHistory} setChatHistory={setChatHistory} language={profile?.language || 'English'} onBack={goBack} onHome={goHome} />;

  return <div className="h-full magic-bg flex items-center justify-center text-white bangers text-4xl">Loading the Magic...</div>;
};

