        <div onClick={onCustom} className={`bg-indigo-900/40 p-6 md:p-8 rounded-[3rem] border-8 border-dashed border-yellow-400/50 cursor-pointer hover:scale-105 transition-all flex flex-col items-center justify-center group min-h-[250px]`}>
          <div className="text-7xl md:text-8xl mb-6 group-hover:rotate-12 transition-transform">🪄</div>
          <span className="text-xl md:text-2xl font-bold text-yellow-400 bangers uppercase tracking-widest text-center">AI Magic Maker</span>
        </div>

        {pool.filter(a => a.isStarter).map(a => (
          <div key={a.id} onClick={() => onSelect(a.id)} className={`bg-white p-6 md:p-8 rounded-[3rem] shadow-2xl border-8 border-white cursor-pointer hover:scale-105 transition-all group flex flex-col items-center min-h-[250px] ${!isPreschool && house ? 'hover:border-yellow-400' : 'hover:border-pink-400'}`}>
            <div className="w-32 h-32 md:w-40 md:h-40 rounded-[2rem] overflow-hidden mb-6 bg-indigo-50 relative">
               <img src={a.image} className="w-full h-full object-cover" alt={a.name} />
               {!isPreschool && house && (
                 <div className={`absolute top-1 right-1 w-8 h-8 md:w-10 md:h-10 rounded-full border-2 border-white ${house.color} flex items-center justify-center text-base md:text-lg`}>
                   {house.icon}
                 </div>
