                   {house.icon}
                 </div>
               )}
            </div>
            <span className="text-xl md:text-2xl font-bold text-indigo-900 bangers uppercase tracking-widest mt-auto text-center">{a.name}</span>
          </div>
        ))}
      </div>
    </div>
