          <input 
            value={prompt} 
            onChange={e => setPrompt(e.target.value)}
            className="w-full p-5 bg-white/10 border-4 border-white/20 rounded-2xl text-xl text-white outline-none focus:border-yellow-400 mb-8 placeholder:text-white/30"
