const PreschoolMap: React.FC<{ onNodeClick: (l: Lesson) => void, profile: any, onAvatarClick: () => void }> = ({ onNodeClick, profile, onAvatarClick }) => {
  const classLevel = profile?.classLevel || 'Preschool';
  const boardKey = 'Common';
  const nodes: Lesson[] = Object.values(SYLLABUS[classLevel]?.[boardKey] || {}).flat() as Lesson[];
  const avatarId = profile?.progress?.currentAvatar;
  const avatar = avatarId === 'custom_ai' ? { image: profile.customAvatarUrl || '' } : (PRESCHOOL_AVATARS.find(a => a.id === avatarId) || PRESCHOOL_AVATARS[0]);

  return (
    <div className="h-full candy-bg relative overflow-y-auto">
      <div className="fixed top-20 left-4 z-40 w-16 h-16 md:w-20 md:h-20 rounded-full border-4 border-white bg-indigo-100 shadow-xl cursor-pointer hover:scale-110 transition-all overflow-hidden" onClick={onAvatarClick}>
        <img src={avatar.image} className="w-full h-full object-cover" alt="Profile" />
      </div>

      <h2 className="text-4xl md:text-5xl font-bold text-pink-500 text-center py-12 bangers tracking-widest drop-shadow-md uppercase px-4">CANDY PATH</h2>
      <div className="flex flex-col items-center relative gap-16 md:gap-20 pb-40">
        <svg className="absolute top-0 w-full h-full min-h-[1200px] pointer-events-none" viewBox="0 0 400 1200" preserveAspectRatio="none">
          <path d="M 200 0 Q 300 200 200 400 Q 100 600 200 800 Q 300 1000 200 1200" fill="none" stroke="#f472b6" strokeWidth="15" className="candy-crush-path opacity-40" strokeLinecap="round" />
        </svg>
        {nodes.map((node, i) => {
